<section class="card" id="members"><div class="section-heading"><h2>用户列表</h2><span class="muted">第 <?= $page ?> 页 · 本页 <?= count($members) ?> 位用户</span></div><form method="get" class="member-search"><input type="hidden" name="section" value="users"><label class="search-field"><span class="sr-only">搜索账号或邮箱</span><?= $icon('search') ?><input name="q" value="<?= $e($q) ?>" placeholder="搜索账号或邮箱"></label><button>搜索</button><?php if($q!==''): ?><a href="?section=users">清除</a><?php endif ?></form><div class="table"><table><thead><tr><th>用户</th><th>邮箱</th><th>状态</th><th>操作</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><div class="table-user"><span class="avatar" aria-hidden="true"><?= $e(mb_substr($m['display_name'],0,1)) ?></span><div><strong><?= $e($m['display_name']) ?></strong><small><?= $e($m['username']) ?></small></div></div></td><td><?= $e($m['email']??'—') ?></td><td><span class="status-pill <?= $m['enabled']?'good':'neutral' ?>"><?= $m['enabled']?'正常':'禁用' ?></span></td><td><?php if($m['role']!=='admin'): ?><form method="post" action="/admin/user"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= $e($m['id']) ?>"><input type="hidden" name="enabled" value="<?= $m['enabled']?'0':'1' ?>"><button class="secondary button-small"><?= $m['enabled']?'禁用':'启用' ?></button></form><?php else: ?><span class="muted">管理员</span><?php endif ?></td></tr><?php endforeach ?><?php if(!$members): ?><tr><td colspan="4"><div class="empty-state"><?= $icon('search') ?><strong><?= $q!==''?'没有找到匹配的用户':'本页暂无用户' ?></strong><p>调整搜索关键词，或返回上一页查看。</p></div></td></tr><?php endif ?></tbody></table></div><div class="pagination"><?php if($page>1): ?><a class="button secondary button-small" href="?section=users&amp;page=<?= $page-1 ?>&amp;q=<?= $e(urlencode($q)) ?>">上一页</a><?php else: ?><span class="button secondary button-small disabled" aria-disabled="true">上一页</span><?php endif ?><span class="muted">第 <?= $page ?> 页</span><a class="button secondary button-small" href="?section=users&amp;page=<?= $page+1 ?>&amp;q=<?= $e(urlencode($q)) ?>">下一页</a></div></section>
<details class="card audit-panel"><summary>登录与管理审计记录<span class="muted">最近 50 条</span></summary><section class="card"><div class="table"><table><thead><tr><th>时间（UTC）</th><th>事件</th><th>账号 ID</th><th>说明</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><?= $e(gmdate('Y-m-d H:i:s',(int)$event['created_at'])) ?></td><td><?= $e($event['event']) ?></td><td><?= $e($event['user_id']??'—') ?></td><td><?= $e($event['detail']) ?></td></tr><?php endforeach ?><?php if(!$events): ?><tr><td colspan="4" class="muted">暂无审计记录。</td></tr><?php endif ?></tbody></table></div></section></details>
